args.command:
python3 - <<'EOF'
import os, glob
candidates = []
for d in ['/usr/bin','/bin','/usr/sbin','/sbin','/usr/lib','/usr/libexec']:
    candidates += glob.glob(d+'/*')
found=[]
for f in candidates:
    try:
        xs = os.listxattr(f)
        if 'security.capability' in xs:
            v = os.getxattr(f,'security.capability')
            found.append((f, v.hex()))
    except OSError:
        pass
print(found[:20])
EOF

